use vstd::vec::Vec;
use vstd::seq::Seq;

verus! {

    /// Delete `p` characters starting at index `at` within the first `l` characters
    /// of `line`, and truncate the vector to length `l - p`.
    fn delete(line: &mut Vec<char>, l: usize, at: usize, p: usize)
        requires
            l <= line.len(),
            at + p <= l,
        ensures
            line.len() == l - p,
        ensures
            line@ == old(line@).slice(0, at)
                    + old(line@).slice(at + p, l)
    {
        // Capture the original contents for our loop‐invariants:
        let old_line = line@;

        let new_len = l - p;
        let mut i = at;

        // Shift the block [at+p .. l) down to [at .. new_len).
        while i < new_len
            invariant at <= i && i <= new_len
            invariant line@.slice(0, at)
                    == old_line.slice(0, at)
            invariant line@.slice(at, i)
                    == old_line.slice(at + p, at + p + (i - at))
            invariant line@.slice(i, l)
                    == old_line.slice(i, l)
        {
            // safe because i + p < new_len + p = l
            line[i] = line[i + p];
            i += 1;
        }

        // Drop the last `p` chars from the first `l` positions,
        // and also remove any extra chars beyond `l`.
        line.truncate(new_len);
    }

}